// Verify HMAC-SHA256 of the raw body against N8N_WEBHOOK_SHARED_SECRET.
// Supabase Database Webhooks sends the signature in X-Webhook-Signature.
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SHARED_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SHARED_SECRET not configured'); }
const sig = $input.first().headers['x-webhook-signature'] || '';
const raw = $input.first().binary?.data?.data
  ? Buffer.from($input.first().binary.data.data, 'base64').toString('utf8')
  : JSON.stringify($input.first().json);
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
  throw new Error('Invalid webhook signature');
}
return [{ json: $input.first().json }];

// Tally intake payload → chatbot_clients.id lookup.
// Supabase REST: GET /rest/v1/chatbot_clients?slug=eq.<slug>&select=id
const tally = $input.first().json;
const slug = tally.slug || tally.body?.slug || tally.client_slug;
if (!slug) { throw new Error('Missing client slug in T+0 payload'); }

const resp = await this.helpers.httpRequest({
  method: 'GET',
  url: `${$env.SUPABASE_URL}/rest/v1/chatbot_clients?slug=eq.${encodeURIComponent(slug)}&select=id,company_name,primary_contact_email`,
  headers: {
    apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`
  },
  json: true
});
if (!Array.isArray(resp) || resp.length === 0) {
  throw new Error(`chatbot_clients row not found for slug=${slug}`);
}
const client = resp[0];
return [{
  json: {
    client_id: client.id,
    company_name: client.company_name,
    contact_email: client.primary_contact_email,
    slug
  }
}];

// Deterministic UUIDv5 — see automations/t-plus-onboarding/README.md §3.
// Fixed Kairikos namespace; safe across re-runs.
const { v5: uuidv5 } = require('uuid');
const NAMESPACE = 'a1b2c3d4-e5f6-4a7b-8c9d-0e1f2a3b4c5d';
const ctx = $input.first().json;
const eventType = 'intake_received';
const dayOffset = 0;
const key = `${eventType}:${ctx.client_id}:${dayOffset}`;
const id = uuidv5(key, NAMESPACE);
return [{
  json: {
    ...ctx,
    activity_id: id,
    event_type: eventType,
    day_offset: dayOffset
  }
}];

// Assemble the final chatbot_activity row.
const emailResp = $input.first().json;
const ctx = $('Build Activity Id (idempotent)').first().json;
const row = {
  id: ctx.activity_id,
  client_id: ctx.client_id,
  day_offset: ctx.day_offset,
  event_type: ctx.event_type,
  title: 'T+0 intake email sent',
  body: null,
  metadata: {
    email_subject: 'Welcome to Kairikos — let\'s get your chatbot live',
    send_status: emailResp.id ? 'sent' : 'failed',
    provider: 'resend',
    email_message_id: emailResp.id || null,
    template: 't-plus-0-intake-v1',
    locale: 'es-ES'
  },
  occurred_at: new Date().toISOString()
};
return [{ json: row }];
